-- Objects of every kind the PostgreSQL scripts handle, with data of every common type.
-- Loaded into a database of their own by test/drivers/pg-scriptObjects.integration.test.ts and
-- test/drivers/pg-scriptDatabase.integration.test.ts.
CREATE SCHEMA app;
COMMENT ON SCHEMA app IS 'Application objects';
CREATE SCHEMA "Odd Schema";
CREATE SCHEMA empty_one;
CREATE TYPE app.mood AS ENUM ('sad', 'ok', 'happy');
CREATE DOMAIN app.positive AS integer DEFAULT 1 NOT NULL CONSTRAINT positive_check CHECK (VALUE > 0);
CREATE TYPE app.pair AS (a integer, b text);
CREATE TYPE app.floatrange AS RANGE (subtype = float8, subtype_diff = float8mi);
COMMENT ON TYPE app.mood IS 'How it feels';
CREATE SEQUENCE app.counter AS integer START WITH 5 INCREMENT BY 5 MINVALUE 5 MAXVALUE 500 CYCLE CACHE 2;
CREATE SEQUENCE app.countdown INCREMENT BY -1;
CREATE FUNCTION app.double(x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x * 2 $$;
CREATE FUNCTION app.double(x numeric) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$ SELECT x * 2 $$;
COMMENT ON FUNCTION app.double(integer) IS 'Twice';
CREATE TABLE app.customers (
    id serial PRIMARY KEY,
    code text COLLATE "C" NOT NULL UNIQUE,
    mood app.mood DEFAULT 'ok',
    qty app.positive,
    price numeric(10, 2) CHECK (price >= 0),
    total numeric GENERATED ALWAYS AS (qty * price) STORED,
    twice integer DEFAULT app.double(3),
    created timestamptz DEFAULT now() NOT NULL
) WITH (fillfactor = 80);
COMMENT ON TABLE app.customers IS 'People who buy';
COMMENT ON COLUMN app.customers.code IS 'Unique code, it''s case sensitive';
CREATE TABLE app.orders (
    id bigint GENERATED ALWAYS AS IDENTITY (START WITH 100 INCREMENT BY 10) PRIMARY KEY,
    customer_id integer NOT NULL REFERENCES app.customers (id) ON DELETE CASCADE,
    note text,
    tags text[]
);
CREATE INDEX orders_note_idx ON app.orders (lower(note)) WHERE note IS NOT NULL;
CREATE TABLE app.events (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    happened date NOT NULL,
    payload jsonb,
    PRIMARY KEY (id, happened)
) PARTITION BY RANGE (happened);
CREATE TABLE app.events_2024 PARTITION OF app.events FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE app.events_rest PARTITION OF app.events DEFAULT;
CREATE INDEX events_payload_idx ON app.events USING gin (payload);
CREATE TABLE "Odd Schema"."Odd ""Table""" ("Col A" integer, "select" text);
CREATE UNLOGGED TABLE app.scratch (k text);
CREATE FUNCTION app.touch() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.note := coalesce(NEW.note, '');
    RETURN NEW;
END
$$;
CREATE TRIGGER orders_touch BEFORE INSERT ON app.orders FOR EACH ROW EXECUTE FUNCTION app.touch();
CREATE TRIGGER orders_off BEFORE UPDATE ON app.orders FOR EACH ROW EXECUTE FUNCTION app.touch();
ALTER TABLE app.orders DISABLE TRIGGER orders_off;
CREATE VIEW app.big_orders WITH (security_barrier = true) AS
    SELECT id, customer_id FROM app.orders WHERE id > 100 WITH LOCAL CHECK OPTION;
CREATE VIEW app.customer_totals AS
    SELECT c.code, count(o.id) AS n FROM app.customers c LEFT JOIN app.orders o ON o.customer_id = c.id GROUP BY c.code;
COMMENT ON VIEW app.customer_totals IS 'Orders per customer';
CREATE VIEW app.top_totals AS SELECT code FROM app.customer_totals WHERE n > 1;
CREATE MATERIALIZED VIEW app.mood_counts AS SELECT mood, count(*) AS n FROM app.customers GROUP BY mood;
CREATE UNIQUE INDEX mood_counts_mood ON app.mood_counts (mood);
CREATE PROCEDURE app.add_order(IN customer integer, IN note text DEFAULT NULL, INOUT new_id bigint DEFAULT NULL)
LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO app.orders (customer_id, note) VALUES (customer, note) RETURNING id INTO new_id;
END
$$;
CREATE FUNCTION app.orders_of(customer integer) RETURNS SETOF app.orders LANGUAGE sql STABLE AS $$
    SELECT * FROM app.orders WHERE customer_id = customer
$$;
CREATE TABLE app.all_types (
    id integer PRIMARY KEY,
    b boolean, i2 smallint, i8 bigint, n numeric, r real, d double precision, m money,
    t text, vc varchar(10), ch char(3), bin bytea, dt date, tm time, tmz timetz,
    ts timestamp, tsz timestamptz, iv interval, u uuid, j json, jb jsonb, x xml,
    a integer[], ta text[], p point, ip inet, net cidr, mac macaddr, bits bit(4), vb varbit,
    tsv tsvector, rng int4range, e app.mood, comp app.pair
);

